#include <QApplication>
#include <QFileDialog>
#include <QLineEdit>
#include <QTemporaryDir>
#include <QFileInfo>
#include <cstdio>
int main(int argc,char** argv) {
    qputenv("QT_QPA_PLATFORM","offscreen");QApplication app(argc,argv);
    QTemporaryDir directory;QFileDialog dialog;
    dialog.setOption(QFileDialog::DontUseNativeDialog);dialog.setAcceptMode(QFileDialog::AcceptSave);
    dialog.setFileMode(QFileDialog::AnyFile);dialog.setDirectory(directory.path());
    dialog.setNameFilter("JSON Tables (*.json)");dialog.show();app.processEvents();
    auto* edit=dialog.findChild<QLineEdit*>("fileNameEdit");if(!edit)return 2;
    edit->setFocus();edit->clear();app.processEvents();
    auto path=directory.filePath("focused.json");dialog.selectFile(path);
    bool old=edit->hasFocus() && edit->text().isEmpty() && dialog.selectedFiles()!=QStringList{path};
    printf("FOCUSED_SELECT_FILE_SKIPS_NAME=%d selected=%s\n",old,dialog.selectedFiles().join(";").toUtf8().constData());
    bool before=dialog.grab().save("build/.ci-tmp/gui-chooser/before-focused.png");
    edit->setText(QFileInfo(path).fileName());
    bool typed=dialog.selectedFiles()==QStringList{path};
    bool after=dialog.grab().save("build/.ci-tmp/gui-chooser/after-focused.png");
    printf("TYPED_FILENAME_SELECTS_PATH=%d screenshots=%d\n",typed,before && after);
    return old && typed && before && after ? 0:1;
}
